123	/// Inputs to the commit op, flat, owned, clap-free: the repos `-s`
124	/// and `-R` resolved to, and the description.
125	#[derive(Debug)]
126	pub struct CommitParams {
127	    /// The pair, work then agent, or the one plain repo.
128	    pub target: Target,
129	    pub title: String,
130	    pub body: String,
131	    /// Make the work commit the merge close-out.
132	    pub closing: bool,
133	    /// Print the descriptions and commit nothing.
134	    pub dry_run: bool,
135	}
136	
137	/// What `-s` resolved to.
138	#[derive(Debug)]
139	pub enum Target {
140	    /// A dual workspace's two repos, work then agent. With
141	    /// `agent_now` the agent commit is made too, else it is left to
142	    /// push, the work commit's trailer naming the agent `@` either
143	    /// way.
144	    Pair { pair: Pair, agent_now: bool },
145	    /// A plain repo with no partner.
146	    Por(PathBuf),
147	}
148	
149	impl TryFrom<&CommitArgs> for CommitParams {
150	    type Error = String;
151	
152	    /// Resolve the scope into its repos, refusing the agent half
153	    /// alone, read the body when it names a file, and check the
154	    /// description is not blank.
155	    fn try_from(a: &CommitArgs) -> Result<Self, String> {
156	        let body = crate::desc_helpers::read_body(&a.body, "commit")?;
157	        if a.title.trim().is_empty() || body.trim().is_empty() {
158	            return Err("commit: --title and --body must both be non-empty".into());
159	        }
160	        if let RepoScope::Sides(sides) = &a.scope
161	            && sides.is_bot_only()
162	        {
163	            return Err(
164	                "commit -s a: the agent half alone is an unpaired commit, since push \
165	                        would commit the work @ with a trailer of its own. Use `-s w` for the \
166	                        work half now and the agent half at push, or `-s b` for both now"
167	                    .into(),
168	            );
169	        }
170	        let target = match &a.scope {
171	            RepoScope::Por => {
172	                let repos = crate::common::resolve_scoped_repos(&a.scope, a.repo.as_deref())
173	                    .map_err(|e| e.to_string())?;
174	                match repos.as_slice() {
175	                    [repo] => Target::Por(repo.clone()),
176	                    other => {
177	                        return Err(format!(
178	                            "commit -s p: expected one repo, got {}",
179	                            other.len()
180	                        ));
181	                    }
182	                }
183	            }
184	            RepoScope::Sides(sides) => {
185	                // Both paths whatever the side, since `w` needs the
186	                // agent @'s change id for its trailer.
187	                let pair = resolve_pair(a.repo.as_deref()).map_err(|e| e.to_string())?;
188	                Target::Pair {
189	                    pair,
190	                    agent_now: sides.is_both(),
191	                }
192	            }
193	        };
194	        Ok(CommitParams {
195	            target,
196	            title: a.title.clone(),
197	            body,
198	            closing: a.closing,
199	            dry_run: a.dry_run.value,
200	        })
201	    }
202	}
