1	//! The `commit` subcommand: make a rung's commit pair, one commit
2	//! per repo of a dual workspace, each stamped with the other's
3	//! change id, before anything is pushed.
4	//!
5	//! The pair is what the per-rung flow reviews: the description and
6	//! the diff together, as a commit, by `jj show @-` in either repo.
7	//! Nothing here reaches a remote, so a fix after the review is a
8	//! fold into the pair and never a remote rewrite, and `vc-x1 push`
9	//! has nothing left to write: it publishes what was reviewed.
10	//!
11	//! - `-s b` makes both commits now. Both change ids are known
12	//!   before either is made, since a jj commit keeps the working
13	//!   copy's change id, so each trailer is written once and never
14	//!   predicted or restamped.
15	//! - `-s w` makes the work commit now, its trailer naming the agent
16	//!   `@` all the same, and leaves the agent half to `push`, which
17	//!   commits the journal as the partner. The pair is then made in
18	//!   two steps, and the review's own transcript lands in the rung's
19	//!   agent commit.
20	//! - `-s a` is refused: an agent commit made first names a work `@`
21	//!   that push would then commit with a trailer of its own, so that
22	//!   direction is where an unpaired commit is real.
23	//! - `-s p` commits a plain repo with the title and body and no
24	//!   trailer, the same description discipline on a repo with no
25	//!   partner.
26	//! - `--body` is the text, or `@PATH` to read it from a file, since
27	//!   a body in commit-body form has markers and blank lines a shell
28	//!   quote mangles.
29	//! - The work side's `@` must hold a change, since a rung changes
30	//!   the work repo. The agent side's `@` is the session's journal
31	//!   and is committed as it stands.
32	//! - `--closing` makes the work commit the cycle's merge close-out:
33	//!   `@`, the closing's edits, is first given `main` and the last
34	//!   rung as its parents, in that order, the trunk first, by the
35	//!   primitive `vc-x1 merge` uses, then committed, which keeps
36	//!   them. `main` is
37	//!   wherever it is now, so one that moved during the cycle is
38	//!   joined by the merge rather than needing a rebase.
39	//!   The title's " closing" or " dead-end closing" suffix is checked
40	//!   against the flag both ways, never its trigger.
41	//! - A failure after the first commit restores both repos from the
42	//!   `jj op` snapshots taken just before it, as push does inside its
43	//!   mutation window.
44	
45	use std::path::{Path, PathBuf};
46	
47	use clap::Args;
48	use log::{debug, info};
49	
50	use crate::context::Context;
51	use crate::desc_helpers::{ochid_prefix_for, with_trailer};
52	use crate::jj;
53	use crate::options_flags::dry_run::DryRunFlag;
54	use crate::options_flags::scope::{REPO_SCOPE_FORMS, RepoScope, repo_scope_parser};
55	use crate::pair::{Pair, Snapshots, resolve_pair};
56	use crate::subcommand::SubcommandRunner;
57	
58	/// Commit the working copies as a rung's pair, or a plain repo's
59	/// commit, with the given title and body.
60	#[derive(Args, Debug)]
61	pub struct CommitArgs {
62	    /// Where: a path in the workspace for `-s b|w`, its root or
63	    /// either repo, or the repo itself for `-s p` [default: the
64	    /// current directory]
65	    #[arg(short = 'R', long, value_name = "PATH")]
66	    pub repo: Option<PathBuf>,
67	
68	    /// Which repos, required: `b|both` makes both commits now,
69	    /// `w|work` the work half with the agent half left to push,
70	    /// `p|por` a plain repo's commit, and `a` is refused
71	    #[arg(
72	        short = 's',
73	        long,
74	        value_name = "SCOPE",
75	        value_parser = repo_scope_parser(&["work", "both", "por"]),
76	        required = true,
77	        help = format!("Which repos, required: {REPO_SCOPE_FORMS}, `a` refused")
78	    )]
79	    pub scope: RepoScope,
80	
81	    /// Commit title, the Conventional Commit line
82	    #[arg(long, value_name = "STR", required = true)]
83	    pub title: String,
84	
85	    /// Commit body, the problem and its solutions, or @PATH to read
86	    /// it from a file
87	    #[arg(long, value_name = "STR|@PATH", required = true)]
88	    pub body: String,
89	
90	    /// Make the work commit the cycle's closing, the merge of the
91	    /// trunk and the ladder; the title must end " closing"
92	    #[arg(long)]
93	    pub closing: bool,
94	
95	    /// Print the descriptions it would write, trailers included, and
96	    /// commit nothing
97	    #[command(flatten)]
98	    pub dry_run: DryRunFlag,
99	}
100	
101	/// Refuse a title whose closing suffix disagrees with `--closing`:
102	/// the flag decides, and the title is transcribed text the check
103	/// catches a slip in. A " closing" title without the flag is a slip
104	/// only when there is a ladder to close: with the work `@-` on
105	/// `main`, a single-step cycle's, it is just a title.
106	fn check_closing_title(title: &str, closing: bool, has_ladder: bool) -> Result<(), String> {
107	    let says_closing = title.trim_end().ends_with(" closing");
108	    if closing && !says_closing {
109	        return Err(format!(
110	            "commit --closing: the title '{title}' does not end \" closing\" or \" dead-end \
111	             closing\", the cycle's closing bookend"
112	        ));
113	    }
114	    if !closing && says_closing && has_ladder {
115	        return Err(format!(
116	            "commit: the title '{title}' ends \" closing\", so it is the cycle's closing \
117	             bookend: pass --closing to make it the merge of the trunk and the ladder"
118	        ));
119	    }
120	    Ok(())
121	}
122	
123	/// Inputs to the commit op, flat, owned, clap-free: the repos `-s`
124	/// and `-R` resolved to, and the description.
125	#[derive(Debug)]
126	pub struct CommitParams {
127	    /// The pair, work then agent, or the one plain repo.
128	    pub target: Target,
129	    pub title: String,
130	    pub body: String,
131	    /// Make the work commit the merge close-out.
132	    pub closing: bool,
133	    /// Print the descriptions and commit nothing.
134	    pub dry_run: bool,
135	}
136	
137	/// What `-s` resolved to.
138	#[derive(Debug)]
139	pub enum Target {
140	    /// A dual workspace's two repos, work then agent. With
141	    /// `agent_now` the agent commit is made too, else it is left to
142	    /// push, the work commit's trailer naming the agent `@` either
143	    /// way.
144	    Pair { pair: Pair, agent_now: bool },
145	    /// A plain repo with no partner.
146	    Por(PathBuf),
147	}
148	
149	impl TryFrom<&CommitArgs> for CommitParams {
150	    type Error = String;
151	
152	    /// Resolve the scope into its repos, refusing the agent half
153	    /// alone, read the body when it names a file, and check the
154	    /// description is not blank.
155	    fn try_from(a: &CommitArgs) -> Result<Self, String> {
156	        let body = crate::desc_helpers::read_body(&a.body, "commit")?;
157	        if a.title.trim().is_empty() || body.trim().is_empty() {
158	            return Err("commit: --title and --body must both be non-empty".into());
159	        }
160	        if let RepoScope::Sides(sides) = &a.scope
161	            && sides.is_bot_only()
162	        {
163	            return Err(
164	                "commit -s a: the agent half alone is an unpaired commit, since push \
165	                        would commit the work @ with a trailer of its own. Use `-s w` for the \
166	                        work half now and the agent half at push, or `-s b` for both now"
167	                    .into(),
168	            );
169	        }
170	        let target = match &a.scope {
171	            RepoScope::Por => {
172	                let repos = crate::common::resolve_scoped_repos(&a.scope, a.repo.as_deref())
173	                    .map_err(|e| e.to_string())?;
174	                match repos.as_slice() {
175	                    [repo] => Target::Por(repo.clone()),
176	                    other => {
177	                        return Err(format!(
178	                            "commit -s p: expected one repo, got {}",
179	                            other.len()
180	                        ));
181	                    }
182	                }
183	            }
184	            RepoScope::Sides(sides) => {
185	                // Both paths whatever the side, since `w` needs the
186	                // agent @'s change id for its trailer.
187	                let pair = resolve_pair(a.repo.as_deref()).map_err(|e| e.to_string())?;
188	                Target::Pair {
189	                    pair,
190	                    agent_now: sides.is_both(),
191	                }
192	            }
193	        };
194	        Ok(CommitParams {
195	            target,
196	            title: a.title.clone(),
197	            body,
198	            closing: a.closing,
199	            dry_run: a.dry_run.value,
200	        })
201	    }
202	}
203	
204	impl SubcommandRunner for CommitArgs {
205	    type Params = CommitParams;
206	
207	    /// Delegate to the `TryFrom<&CommitArgs>` impl above.
208	    fn to_params(&self) -> Result<Self::Params, String> {
209	        CommitParams::try_from(self)
210	    }
211	
212	    /// Run the `commit` op.
213	    fn run(ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
214	        commit(ctx, params)
215	    }
216	}
217	
218	/// Entry point: the pair, or the plain commit.
219	pub fn commit(ctx: &mut Context, params: &CommitParams) -> Result<(), Box<dyn std::error::Error>> {
220	    debug!("commit: enter {params:?}");
221	    match &params.target {
222	        Target::Pair { pair, agent_now } => commit_pair(ctx, pair, *agent_now, params),
223	        Target::Por(repo) => commit_por(ctx, repo, params),
224	    }
225	}
226	
227	/// Refuse a repo that cannot take the commit: a conflicted one, or
228	/// for the work side an empty `@`, since a rung changes the work
229	/// repo and an empty commit would carry a trailer naming nothing
230	/// worth reviewing.
231	fn preflight(
232	    repo: &Path,
233	    label: &str,
234	    must_change: bool,
235	) -> Result<(), Box<dyn std::error::Error>> {
236	    crate::pair::refuse_conflicts(repo, "commit", label)?;
237	    if must_change && jj::is_empty(repo, "@")? {
238	        return Err(format!(
239	            "commit: nothing to commit, the {label} repo's @ is empty ('{}')",
240	            repo.display()
241	        )
242	        .into());
243	    }
244	    Ok(())
245	}
246	
247	/// Make the pair: both change ids read from the working copies
248	/// first, then the work commit with the agent's id in its trailer
249	/// and, with `agent_now`, the agent commit with the work's id in
250	/// its own. Without it the agent `@` is left for push to commit as
251	/// the partner, its id already in the work commit's trailer.
252	fn commit_pair(
253	    ctx: &mut Context,
254	    pair: &Pair,
255	    agent_now: bool,
256	    params: &CommitParams,
257	) -> Result<(), Box<dyn std::error::Error>> {
258	    let (work, agent) = (pair.work.as_path(), pair.agent.as_path());
259	    preflight(work, "work", true)?;
260	    preflight(agent, "agent", false)?;
261	    check_closing(params, work)?;
262	    let work_chid = jj::chid_of(work, "@")?;
263	    let agent_chid = jj::chid_of(agent, "@")?;
264	    let agent_prefix = ochid_prefix_for(agent)?;
265	    let text = format!("{}\n\n{}", params.title, params.body);
266	    let work_desc = with_trailer(&text, &format!("{agent_prefix}{agent_chid}"));
267	    let agent_desc = with_trailer(&text, &format!("/{work_chid}"));
268	    let merge = if params.closing {
269	        Some(closing_parents(work)?)
270	    } else {
271	        None
272	    };
273	
274	    if params.dry_run {
275	        if let Some((base, tip)) = &merge {
276	            info!(
277	                "commit: [dry-run] the work commit is the merge of the fork point {base} and the last rung {tip}"
278	            );
279	        }
280	        info!(
281	            "commit: [dry-run] the work commit {work_chid}, in {}:\n{work_desc}",
282	            work.display()
283	        );
284	        if agent_now {
285	            info!(
286	                "commit: [dry-run] the agent commit {agent_chid}, in {}:\n{agent_desc}",
287	                agent.display()
288	            );
289	        } else {
290	            info!(
291	                "commit: [dry-run] the agent @ {agent_chid} is left for push to commit as the partner"
292	            );
293	        }
294	        return Ok(());
295	    }
296	    let snapshots = Snapshots::take(pair)?;
297	    if let Some((base, tip)) = &merge
298	        && let Err(e) = make_closing_merge(ctx, work, base, tip)
299	    {
300	        snapshots.restore(pair, "commit", e.as_ref());
301	        return Err(e);
302	    }
303	    info!("commit work: {} -> @- {work_chid}", work.display());
304	    if let Err(e) = ctx.session(work)?.commit(&work_desc) {
305	        snapshots.restore(pair, "commit", e.as_ref());
306	        return Err(e);
307	    }
308	    if !agent_now {
309	        info!(
310	            "commit: the work half is made, its trailer naming the agent @ {agent_chid}, which \
311	             push commits as the partner. Review it with `jj show @- -R {}`",
312	            work.display()
313	        );
314	        return Ok(());
315	    }
316	    info!("commit agent: {} -> @- {agent_chid}", agent.display());
317	    if let Err(e) = ctx.session(agent)?.commit(&agent_desc) {
318	        snapshots.restore(pair, "commit", e.as_ref());
319	        return Err(e);
320	    }
321	    info!(
322	        "commit: the pair is made, review it with `jj show @- -R {}` and `jj show @- -R {}`",
323	        work.display(),
324	        agent.display()
325	    );
326	    Ok(())
327	}
