575: /// What the commit does to bookmarks, resolved before anything is
576: /// made: where `--opening`'s bookmark starts, and the bookmark
577: /// advanced to the work commit.
578: #[derive(Debug)]
579: struct BookmarkPlan {
580:     start: Option<String>,
581:     advance: Option<String>,
582: }
583: 
584: /// Resolve the bookmark plan, refusing before anything is made: the
585: /// opening's checks, then the bookmark to advance, `--opening`'s, the
586: /// one named, which must be among the nearest below the work `@-` as
587: /// `push` requires, or the line's, refused when there are none or
588: /// several, since a wrong guess moves the wrong branch.
589: fn plan_bookmarks(
590:     repo: &Path,
591:     params: &CommitParams,
592: ) -> Result<BookmarkPlan, Box<dyn std::error::Error>> {
593:     let start = match &params.opening {
594:         Some(o) => Some(check_opening(repo, o)?),
595:         None => None,
596:     };
597:     let advance = match (&params.advance, &params.opening) {
598:         (Advance::Off, _) => None,
599:         (_, Some(o)) => Some(o.bookmark.clone()),
600:         (Advance::Named(b), None) => {
601:             let nearest = jj::local_bookmarks_at(repo, "heads(::@- & bookmarks())")?;
602:             if !nearest.contains(b) {
603:                 return Err(format!(
604:                     "commit --bookmark: '{b}' is not the nearest bookmark below the work @- in {}, \
605:                      the line's own ({})",
606:                     repo.display(),
607:                     nearest.join(", ")
608:                 )
609:                 .into());
610:             }
611:             Some(b.clone())
612:         }
613:         (Advance::Line, None) => Some(crate::squash_push::current_bookmark(repo, "@-").map_err(
614:             |e| format!("commit: {e} with --bookmark <NAME>, or pass --no-advance to move none"),
615:         )?),
616:     };
617:     Ok(BookmarkPlan { start, advance })
618: }
619: 
620: /// What the bookmark plan would do, for a dry run.
621: fn dry_run_bookmarks(params: &CommitParams, plan: &BookmarkPlan) {
622:     if let (Some(o), Some(start)) = (&params.opening, &plan.start) {
623:         dry_run_opening(o, start);
624:     }
625:     if let Some(name) = &plan.advance {
626:         info!("commit: [dry-run] advance '{name}' to the work commit, locally");
627:     }
628: }
629: 
630: /// Carry out the bookmark plan once the commits are made, so a failed
631: /// commit moves no bookmark: the opening's bookmark created at its
632: /// start and pushed, then the advance to the work commit, the work
633: /// `@-` now.
634: fn finish_bookmarks(
635:     ctx: &mut Context,
636:     repo: &Path,
637:     params: &CommitParams,
638:     plan: &BookmarkPlan,
639: ) -> Result<(), Box<dyn std::error::Error>> {
640:     if let (Some(o), Some(start)) = (&params.opening, &plan.start) {
641:         make_opening_bookmark(ctx, repo, o, start)?;
642:     }
643:     if let Some(name) = &plan.advance {
644:         info!("commit: advance '{name}' to the work commit, locally");
645:         ctx.session(repo)?.bookmark_set(name, "@-")?;
646:     }
647:     Ok(())
648: }
649: 
650: /// `--opening`'s bookmark checked before anything is made, returning
651: /// the commit id of the work `@-`, where the cycle's branch starts and
652: /// the bookmark goes. A bookmark created here must not exist, and one
653: /// taken by `--skip` must be at `@-` already. A push must not move a
654: /// remote bookmark elsewhere, and `@-` must already be on a remote, so
655: /// the push publishes a name and nothing unreviewed.
656: fn check_opening(repo: &Path, o: &Opening) -> Result<String, Box<dyn std::error::Error>> {
657:     let name = &o.bookmark;
658:     let start = jj::cid_of(repo, "@-")?;
659:     let exists = jj::local_bookmark_exists(repo, name)?;
660:     if o.creates() && exists {
661:         return Err(format!(
662:             "commit --opening: the bookmark '{name}' exists in {} already: --skip local takes \
663:              one at the work @- and pushes it, --skip both only checks it",
664:             repo.display()
665:         )
666:         .into());
667:     }
668:     if !o.creates() && !jj::local_bookmarks_at(repo, "@-")?.contains(name) {
669:         return Err(format!(
670:             "commit --opening --skip: the bookmark '{name}' is not at the work @- {start} in {}, \
671:              where the cycle's branch starts",
672:             repo.display()
673:         )
674:         .into());
675:     }
676:     if o.pushes() {
677:         if let Some(at) = jj::remote_bookmark_targets(repo, "origin")?.get(name.as_str())
678:             && *at != start
679:         {
680:             return Err(format!(
681:                 "commit --opening: the bookmark '{name}' is on origin at {at}, not the work @- \
682:                  {start}, and the opening moves no published bookmark"
683:             )
684:             .into());
685:         }
686:         if !jj::matches(repo, "@- & ::remote_bookmarks()")? {
687:             return Err(format!(
688:                 "commit --opening: the work @- {start} is on no remote, so pushing '{name}' at it \
689:                  would publish unreviewed commits: --skip remote creates it and pushes nothing"
690:             )
691:             .into());
692:         }
693:     }
694:     Ok(start)
695: }
696: 
697: /// What `--opening` would do to its bookmark, for a dry run.
698: fn dry_run_opening(o: &Opening, start: &str) {
699:     let name = &o.bookmark;
700:     match (o.creates(), o.pushes()) {
701:         (true, true) => info!("commit: [dry-run] create '{name}' at {start} and push it to origin"),
702:         (true, false) => info!("commit: [dry-run] create '{name}' at {start}, pushing nothing"),
703:         (false, true) => info!("commit: [dry-run] push '{name}', at {start} already, to origin"),
704:         (false, false) => info!("commit: [dry-run] '{name}' is at {start} already, nothing to do"),
705:     }
706: }
707: 
708: /// Create `--opening`'s bookmark at `start` and push it, as `--skip`
709: /// says, after the commit, so a failed commit leaves no bookmark. A
710: /// failed push leaves the opening and the local bookmark, which the
711: /// push after the review publishes.
712: fn make_opening_bookmark(
713:     ctx: &mut Context,
714:     repo: &Path,
715:     o: &Opening,
716:     start: &str,
717: ) -> Result<(), Box<dyn std::error::Error>> {
718:     let name = &o.bookmark;
719:     if o.creates() {
720:         info!("commit --opening: create '{name}' at {start}");
721:         ctx.session(repo)?.bookmark_set(name, start)?;
722:     }
723:     if o.pushes() {
724:         info!("commit --opening: push '{name}' to origin");
725:         ctx.session(repo)?.git_push_bookmark(name).map_err(|e| {
726:             format!(
727:                 "commit --opening: the opening is made and '{name}' is at {start} locally, but \
728:                  its push failed: {e}. The push after the review publishes both"
729:             )
730:         })?;
731:     }
732:     Ok(())
733: }
734: 
735: /// Whether the work `@-` is a ladder above `main`, one a closing
736: /// closes: not `main` and not contained in it.
737: fn has_ladder(repo: &Path) -> Result<bool, Box<dyn std::error::Error>> {
738:     Ok(!jj::matches(repo, "@- & ::main")?)
739: }
740: 
741: /// The closing's two sources, as commit ids read before anything
742: /// moves: `main` first, wherever it is now, so a `main` that moved
743: /// during the cycle is joined by the merge rather than needing a
744: /// rebase, and the last rung, the work `@-`, second. Refused when
745: /// there is no ladder, the last rung being in `main` already.
746: fn closing_parents(repo: &Path) -> Result<(String, String), Box<dyn std::error::Error>> {
747:     if !has_ladder(repo)? {
748:         return Err(
749:             "commit --closing: the work @- is in `main`, so there is no ladder to close. \
750:                     A closing is made on the cycle's last rung"
751:                 .into(),
