    let chid = jj::chid_of(repo, "@-")?;
    if dry_run {
        if fold {
            info!("commit: [dry-run] fold the work @ into @- {chid}");
        }
        info!("commit: [dry-run] finalize @- {chid}, in {}:\\n{desc}", repo.display());
        return Ok(());
