    let result = (|| -> Result<(), Box<dyn std::error::Error>> {
        if fold {
            info!("commit work: @ -> @- {chid}");
            ctx.session(repo)?.squash_into("@", "@-")?;
        }
        info!("commit work: finalize @- {chid} as '{title}', its trailer kept");
        ctx.session(repo)?.describe("@-", &desc)
